SELECT * FROM task_failure_diagnoses
WHERE task_id = #{taskId}
ORDER BY created_at DESC, id DESC

SELECT * FROM task_failure_diagnoses
WHERE signature = #{signature}
  AND source = 'AI'
  AND created_at >= #{since}
ORDER BY created_at DESC, id DESC
LIMIT 1

mapper.update:
UPDATE task_failure_diagnoses
SET reviewed_at = #{reviewedAt}, reviewed_by = #{reviewedBy}
WHERE id = #{id}
